//! Genuine RustPython object identity prerequisite, never production execution.
//! Geometry is an owned typed triangle callback; full Mesh/Group API is open.
use crate::{face_owner::{FaceOwner,FaceTransaction},owner_budget::{Kind,Lease},session};
use rustpython_vm::{Interpreter,InterpreterBuilder,scope::Scope,compiler::Mode,pymodule,PyRef};
use ingetrazo_core::mesh::Mesh;use glam::DVec3;use std::{cell::RefCell,rc::Rc};
struct Stage{transaction:FaceTransaction,handles:Vec<PyRef<native_faces::Face>>,charge:Lease,handle_limit:Option<usize>}
struct Command{base:usize,handles:Vec<PyRef<native_faces::Face>>,_charge:Lease}
struct State{owner:FaceOwner,live_count:usize,undo:Vec<Command>,redo:Vec<Command>}
thread_local!{static STAGED:RefCell<Option<Stage>>=const{RefCell::new(None)};static ACTIVE:RefCell<Option<Rc<RefCell<State>>>>=const{RefCell::new(None)};}
struct Guard;
impl Drop for Guard{fn drop(&mut self){ACTIVE.with(|s|drop(s.borrow_mut().take()));STAGED.with(|s|drop(s.borrow_mut().take()));}}
#[pymodule]pub mod native_faces{
 use rustpython_vm::{pyclass,Traverse,Py,PyRef,PyPayload,PyObjectRef,PyResult,VirtualMachine,builtins::PyListRef,function::ArgIntoFloat,common::lock::PyRwLock};
 #[pyattr]#[pyclass(name="Face",traverse)]#[derive(Debug,PyPayload)]
 pub struct Face{pub(super) attrs:PyRwLock<PyObjectRef>}
 #[pyclass]impl Face{
  #[pygetset]fn attrs(zelf:&Py<Self>)->PyObjectRef{zelf.attrs.read().clone()}
  #[pygetset(setter)]fn set_attrs(zelf:&Py<Self>,value:PyObjectRef,vm:&VirtualMachine)->PyResult<()>{vm.host_budget_tick()?;let old={let mut attrs=zelf.attrs.write();std::mem::replace(&mut *attrs,value)};drop(old);Ok(())}
 }
 /// Fixed typed triangle admission is intentionally not renamed Mesh.add_face.
 #[pyfunction]fn triangle(z:ArgIntoFloat,vm:&VirtualMachine)->PyResult<PyRef<Face>>{
  vm.host_budget_tick()?;let z=z.into_float();let face=Face{attrs:PyRwLock::new(vm.ctx.new_dict().into())}.into_ref(&vm.ctx);
  let result=super::STAGED.with(|slot|{let mut slot=slot.borrow_mut();let stage=slot.as_mut().ok_or("No active face transaction")?;let next=stage.handles.len().checked_add(1).ok_or("Handle staging extent overflow")?;if stage.handle_limit.is_some_and(|limit|next>limit){return Err("Face handle staging admission denied".into());}stage.handles.try_reserve(1).map_err(|_|"Face handle staging refused")?;stage.charge.resize(stage.handles.capacity().checked_mul(std::mem::size_of::<PyRef<Face>>()).ok_or("Handle staging byte overflow")?)?;stage.transaction.add_face(&[super::DVec3::new(0.,0.,z),super::DVec3::new(1.,0.,z),super::DVec3::new(0.,1.,z)],&[])?;stage.handles.push(face.clone());Ok::<_,String>(())});if result.is_err(){super::STAGED.with(|slot|{if let Some(stage)=slot.borrow_mut().as_mut(){stage.transaction.abort();}});}result.map_err(|e|vm.new_value_error(e))?;Ok(face)
 }
 #[pyfunction]fn faces(vm:&VirtualMachine)->PyResult<PyListRef>{vm.host_budget_tick()?;let mut out:Vec<PyObjectRef>=super::ACTIVE.with(|slot|{let slot=slot.borrow();let state=slot.as_ref().ok_or("No active face owner")?.borrow();let mut out=Vec::new();out.try_reserve_exact(state.live_count).map_err(|_|"Face query allocation refused")?;for c in &state.undo{out.extend(c.handles.iter().cloned().map(Into::into));}Ok::<_,String>(out)}).map_err(|e|vm.new_runtime_error(e))?;let result=super::STAGED.with(|slot|{if let Some(stage)=slot.borrow().as_ref(){out.try_reserve(stage.handles.len()).map_err(|_|"Staged face query refused")?;out.extend(stage.handles.iter().cloned().map(Into::into));}Ok::<_,String>(())});result.map_err(|e|vm.new_runtime_error(e))?;Ok(vm.ctx.new_list(out))}

}
impl State{
 fn publish(&mut self,mut stage:Stage)->Result<bool,String>{let count=stage.handles.len();if count==0{return self.owner.commit(stage.transaction);}let base=self.live_count;let extent=base.checked_add(count).ok_or("Handle publication extent overflow")?;self.undo.try_reserve(1).map_err(|_|"Handle history refused")?;let bytes=stage.handles.capacity().checked_mul(std::mem::size_of::<PyRef<native_faces::Face>>()).and_then(|n|n.checked_add(std::mem::size_of::<Command>())).ok_or("Handle history overflow")?;stage.charge.resize(bytes)?;stage.charge.reclassify(Kind::History)?;if !self.owner.commit(stage.transaction)?{return Err("Face handle publication mismatch".into());}self.live_count=extent;self.redo.clear();self.undo.push(Command{base,handles:stage.handles,_charge:stage.charge});Ok(true)}
 fn undo(&mut self)->Result<bool,String>{let Some(c)=self.undo.last()else{return Ok(false)};if self.live_count!=c.base.checked_add(c.handles.len()).ok_or("Handle extent overflow")?{return Err("Handle undo ownership mismatch".into());}self.redo.try_reserve(1).map_err(|_|"Handle redo slots refused")?;if !self.owner.undo()?{return Err("Handle/face history mismatch".into());}let c=self.undo.pop().unwrap();self.live_count=c.base;self.redo.push(c);Ok(true)}
 fn redo(&mut self)->Result<bool,String>{let Some(c)=self.redo.last()else{return Ok(false)};if self.live_count!=c.base{return Err("Handle redo ownership mismatch".into());}let extent=c.base.checked_add(c.handles.len()).ok_or("Handle redo extent overflow")?;self.undo.try_reserve(1).map_err(|_|"Handle undo slots refused")?;if !self.owner.redo()?{return Err("Handle/face redo mismatch".into());}let c=self.redo.pop().unwrap();self.live_count=extent;self.undo.push(c);Ok(true)}
}
#[derive(Debug)]pub enum Failure{Python(rustpython_vm::builtins::PyBaseExceptionRef),Preparation(String)}

pub struct Controller{scope:Scope,state:Rc<RefCell<State>>,interpreter:Interpreter,tainted:bool,handle_limit:Option<usize>}
impl Controller{
 pub fn new()->Result<Self,String>{let owner=FaceOwner::new(Mesh::new())?;let builder=InterpreterBuilder::new();let module=native_faces::module_def(&builder.ctx);let interpreter=builder.add_native_module(module).interpreter();let scope=interpreter.enter(|vm|{let scope=vm.new_scope_with_builtins();vm.run_code_obj(vm.compile("import native_faces",Mode::Exec,"<setup>").unwrap(),scope.clone()).unwrap();scope});Ok(Self{interpreter,scope,state:Rc::new(RefCell::new(State{owner,live_count:0,undo:vec![],redo:vec![]})),tainted:false,handle_limit:None})}
 /// Scope/VM are private; reset happens only after taken staging is discarded.
 pub fn execute(&mut self,source:&str,fuel:u64)->Result<bool,Failure>{if self.tainted{return Err(Failure::Preparation("Unfinished VM execution; reuse refused".into()));}if STAGED.with(|s|s.borrow().is_some())||ACTIVE.with(|s|s.borrow().is_some()){return Err(Failure::Preparation("Nested controller admission refused".into()));}let stage={let s=self.state.borrow();Stage{transaction:s.owner.begin().map_err(Failure::Preparation)?,handles:vec![],charge:s.owner.budget().reserve(Kind::Staging,0).map_err(Failure::Preparation)?,handle_limit:self.handle_limit}};let state=self.state.clone();let scope=self.scope.clone();self.tainted=true;let result=self.interpreter.enter(|vm|{vm.host_budget_arm(fuel).map_err(|e|Failure::Preparation(e.to_owned()))?;STAGED.with(|s|*s.borrow_mut()=Some(stage));ACTIVE.with(|s|*s.borrow_mut()=Some(state.clone()));let _guard=Guard;let result=session::execute(vm,&scope,source);let poisoned=vm.host_budget_poisoned();ACTIVE.with(|s|drop(s.borrow_mut().take()));let stage=STAGED.with(|s|s.borrow_mut().take()).unwrap();let result=if poisoned{drop(stage);Err(match result{Err(exception)=>Failure::Python(exception),Ok(())=>Failure::Preparation("Poisoned execution cannot publish".into())})}else{match result{Ok(())=>state.borrow_mut().publish(stage).map_err(Failure::Preparation),Err(exception)=>{drop(stage);Err(Failure::Python(exception))}}};assert!(STAGED.with(|s|s.borrow().is_none()));vm.host_budget_reset_after_discard();result});self.tainted=false;result}
 /// Engineering observation only: reads literal fixture primitives, never
 /// converts document attribute objects to JSON for storage/publication.
 pub fn observe(&self,name:&str)->serde_json::Value{use rustpython_vm::{AsObject,builtins::{PyDict,PyList,PyStr}};self.interpreter.enter(|vm|{let a=self.scope.globals.get_item("a",vm).unwrap().downcast::<native_faces::Face>().unwrap();let shared=self.scope.globals.get_item("shared",vm).unwrap();let state=self.state.borrow();let live:Vec<_>=state.undo.iter().flat_map(|c|c.handles.iter()).collect();let value=|f:&PyRef<native_faces::Face>,key:&str|{f.attrs.read().clone().downcast::<PyDict>().unwrap().get_item(key,vm).unwrap()};let strings=|obj:&rustpython_vm::PyObjectRef|{obj.downcast_ref::<PyList>().unwrap().borrow_vec().iter().map(|x|x.downcast_ref::<PyStr>().unwrap().as_wtf8().to_string()).collect::<Vec<_>>()};let first=live.first().map(|f|value(f,"shared"));let keys=live.first().map(|f|{let d=value(f,"non_string_keys").downcast::<PyDict>().unwrap();let mut names=d.into_iter().map(|(k,_)|k.class().name().to_string()).collect::<Vec<_>>();names.sort();names}).unwrap_or_default();serde_json::json!({"name":name,"faces":live.len(),"held_is_live":live.iter().any(|f|f.is(&a)),"shared_alias":live.len()==2&&value(live[0],"shared").is(&value(live[1],"shared")),"shared_is_scope":first.as_ref().is_some_and(|x|x.is(&shared)),"tuple_type":live.first().map(|f|value(f,"tuple").class().name().to_string()),"held_shared_value":strings(&value(&a,"shared")),"scope_shared_value":strings(&shared),"live_shared_values":live.iter().map(|f|strings(&value(f,"shared"))).collect::<Vec<_>>(),"nonstring_keys":keys})})}
 pub fn budget(&self)->crate::owner_budget::OwnerBudget{self.state.borrow().owner.budget()}
 pub fn set_handle_limit(&mut self,limit:Option<usize>){self.handle_limit=limit;}
 pub fn undo(&mut self)->Result<bool,String>{self.state.borrow_mut().undo()}
 pub fn redo(&mut self)->Result<bool,String>{self.state.borrow_mut().redo()}
 pub fn mesh_counts(&self)->(usize,usize,usize){let s=self.state.borrow();(s.owner.mesh().vertices.len(),s.owner.mesh().edges.len(),s.owner.mesh().faces.len())}
 pub fn history_counts(&self)->(usize,usize){let s=self.state.borrow();(s.undo.len(),s.redo.len())}
}
